#define CAM_SPEED_X 0.0
#define CAM_SPEED_Y 0.0
#define CAM_DIST 0.20985401459854014
#define CAM_Z -0.5474452554744524

#define FOV_FACTOR 1.25
#define ROT_SPEED 0.8941605839416058

#define MAX_STEPS 97
#define GLOW_ATTENUATION 43.79562043795621
#define GLOW_INTENSITY 0.017107664233576642

#define BASE_SCALE 2.1496350364963503
#define FRACTAL_ITERS 4
#define INVERSION_NUM 5.518248175182482
#define INVERSION_MIN 1.0748175182481752
#define OFFSET_XYZ vec3(3.8, 3.8, -0.4)

#define FINAL_POWER 3.908759124087591

vec3 palette(in float t) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 0.5, 0.5);
    vec3 c = vec3(1.0, 1.0, 1.0);
    vec3 d = vec3(0.00, 0.33, 0.67);
    return a + b * cos(6.28318 * (c * t + d));
}

vec3 render(vec2 coordonneesPixel, vec2 resolution) {
    float temps = iTime;

    vec3 positionCamera = vec3(sin(temps * CAM_SPEED_X), cos(temps * CAM_SPEED_Y), CAM_Z) * CAM_DIST;

    vec2 uv = (coordonneesPixel * 2.0 - resolution) / resolution.y;
    vec3 directionRayon = normalize(vec3(uv, FOV_FACTOR));

    mat2 matriceRotation = mat2(cos(temps * ROT_SPEED + vec4(0.0, 33.0, 11.0, 0.0)));

    vec3 couleurCumulee = vec3(0.0);
    float distanceEstimation = 0.0;
    float facteurEchelleGlobal;

    vec3 positionRayon = positionCamera;
    vec3 positionEspaceLocal;

    for (int etape = 0; etape < MAX_STEPS; etape++) {
        positionRayon += directionRayon * distanceEstimation;

        float pScalaireMem = 0.0;
        positionEspaceLocal = positionRayon;
        positionEspaceLocal.yz *= matriceRotation;
        positionEspaceLocal = 1.0 - abs(positionEspaceLocal);

        facteurEchelleGlobal = BASE_SCALE;

        for (int iterationFractale = 0; iterationFractale < FRACTAL_ITERS; iterationFractale++) {
            positionEspaceLocal = abs(positionEspaceLocal) - 1.0;

            float produitScalaire = dot(positionEspaceLocal, positionEspaceLocal);
            float facteurInversion = INVERSION_NUM / min(produitScalaire, INVERSION_MIN);

            facteurEchelleGlobal *= facteurInversion;
            positionEspaceLocal = abs(positionEspaceLocal) * facteurInversion - OFFSET_XYZ;
            pScalaireMem += produitScalaire;
        }

        float rayonXZ = length(positionEspaceLocal.xz);
        distanceEstimation = rayonXZ / facteurEchelleGlobal;

        float facteurGlow = exp(-distanceEstimation * GLOW_ATTENUATION) * GLOW_INTENSITY;
        vec3 couleurTeinte = palette(pScalaireMem * 0.05 + temps * 0.1);
        couleurCumulee += couleurTeinte * facteurGlow;
    }

    vec3 couleurFinale = vec3(1.0) - exp(-pow(couleurCumulee, vec3(FINAL_POWER)));

    vec2 uvNorm = coordonneesPixel / resolution;
    float vignette = uvNorm.x * uvNorm.y * (1.0 - uvNorm.x) * (1.0 - uvNorm.y);
    vignette = clamp(pow(16.0 * vignette, 0.25), 0.0, 1.0);

    return couleurFinale * vignette;
}

void mainImage(out vec4 couleurSortie, vec2 coordonneesPixel) {
    vec2 resolution = iResolution.xy;

    vec3 col = vec3(0.0);
    vec2 offsets[4];
    offsets[0] = vec2(-0.25, -0.25);
    offsets[1] = vec2( 0.25, -0.25);
    offsets[2] = vec2(-0.25,  0.25);
    offsets[3] = vec2( 0.25,  0.25);

    for (int i = 0; i < 4; i++) {
        col += render(coordonneesPixel + offsets[i], resolution);
    }
    col *= 0.25;

    col = pow(col, vec3(1.0 / 2.2));

    couleurSortie = vec4(col, 1.0);
}
